"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.26825",title:"MemT-1.0: Towards Memory-Native Evolution",up:126,href:"https://arxiv.org/abs/2610.26825",abstract:"Memory-native evolution requires making memory an intrinsic capability of foundation models, enabling them to continuously accumulate and utilize information. To this end, we introduce MemT-1.0, a new architecture of memory foundation models that internalize memory as part of model computation. Building on Metis, MemT-1.0 employs Gated DeltaNet-2 with a stable token-level memory update mechanism within each turn. We further introduce Mixture-of-Storage to scale native memory capacity. Following a deliberate backbone preparation, we develop a two-stage training pipeline consisting of continued ",pdfUrl:"https://arxiv.org/pdf/2610.26825",primaryCategory:"cs.CL",published:"2026-10-19T00:00:00Z"},{id:"2610.25736",title:"Learning from Fleet Experience: A Collective Learning Paradigm for Robots",up:93,href:"https://arxiv.org/abs/2610.25736",abstract:"Experience generated during deployment offers an opportunity for robots to improve policy reliability through learning from their own executions. However, learning through human corrections requires teleoperators to monitor execution and intervene when policies fail, a demand that is difficult to meet as robot fleets grow. We introduce collective experience learning (CEL), a learning paradigm in which deployed robots share their execution experience to improve a common policy. We realize CEL through failure-guided experience retrieval fine-tuning (FERT), which uses failure contexts from robot ",pdfUrl:"https://arxiv.org/pdf/2610.25736",primaryCategory:"cs.RO",published:"2026-10-19T00:00:00Z"},{id:"2610.26802",title:"Scaling Parameter-Efficient Fine-Tuning for Brain Encoding",up:69,href:"https://arxiv.org/abs/2610.26802",abstract:"Brain encoding models aim to predict neural responses to stimuli. The most widely used approach fits readouts from frozen pretrained backbones. Using neural data to train large models from scratch or fully fine-tune them after task-pretraining has proven difficult because neural data is costly and limited. We show that parameter-efficient fine-tuning (PEFT) enables us to effectively adapt very large pretrained backbones for brain encoding with a small number of trainable parameters. To make it computationally practical, we exploit the backbone's causal structure to predict multiple timepoints ",pdfUrl:"https://arxiv.org/pdf/2610.26802",primaryCategory:"cs.LG",published:"2026-10-19T00:00:00Z"},{id:"2610.26625",title:"EgoXperience: Learning World-Grounded Egocentric Representations from Human Experience",up:66,href:"https://arxiv.org/abs/2610.26625",abstract:"Reconstructing human activity from egocentric video requires more than recovering individual 3D components: the observer's motion, surrounding geometry, and hand-object interactions must fit together in a consistent world. Achieving this coherence requires both joint reconstruction and aligned supervision, yet existing methods and datasets offer limited support for either. We present EgoXperience, a full-stack paradigm that addresses these needs through data collection, automatic annotation, unified modeling, and benchmarking. Central to EgoXperience is an automatic annotation engine, EgoX-Eng",pdfUrl:"https://arxiv.org/pdf/2610.26625",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.26549",title:"Holi-World: Building Holistic World Intelligence from Human-Ego Experience",up:64,href:"https://arxiv.org/abs/2610.26549",abstract:"Human egocentric experience offers a rich foundation for learning how the world is organized and how it changes through interaction. Realizing this potential at scale requires turning growing volumes of recordings into learning resources that connect scene structure, object semantics, and interaction histories across viewpoints and time, while reducing dependence on costly manual annotation. We introduce HOLI-WORLD, an integrated ecosystem connecting experience capture, world representation, automated data construction, model learning, and independent evaluation. To sup- port learning at scale",pdfUrl:"https://arxiv.org/pdf/2610.26549",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.26860",title:"OpenVLHarness: Real World Visual Agentic Tool-Use with Multimodal Memory",up:62,href:"https://arxiv.org/abs/2610.26860",abstract:"Multimodal large language models (MLLMs) have made rapid progress on visual reasoning, yet many tasks require evidence that is difficult to obtain through internal reasoning alone: our controlled study on 22 benchmarks shows that simply increasing the inference budget of the base model yields only modest gains. Such tasks demand grounded perception, external knowledge, and numerical measurements obtained through heterogeneous tools, whose outputs must be made interpretable to the model and retained across reasoning steps. We introduce OpenVLHarness, a multimodal reasoning harness organized aro",pdfUrl:"https://arxiv.org/pdf/2610.26860",primaryCategory:"cs.CL",published:"2026-10-19T00:00:00Z"},{id:"2610.25690",title:"ScaleNav: Scalable Internet Video Pretraining for Language-Conditioned Local Navigation",up:55,href:"https://arxiv.org/abs/2610.25690",abstract:"We study language-conditioned local navigation, where a robot must navigate to a text-specified target visible in its initial observation and stop at the described location. End-to-end navigation policies require diverse training data to generalize across scenes, yet real-robot data is costly to collect and simulated data leaves a sim-to-real gap. Internet egocentric videos offer a scalable source of real-world navigation experience. Our key insight is to learn goal-directed visual dynamics from Internet egocentric videos, and use these dynamics to support robot action generation. To this end,",pdfUrl:"https://arxiv.org/pdf/2610.25690",primaryCategory:"cs.RO",published:"2026-10-19T00:00:00Z"},{id:"2610.26824",title:"SpecMRL: Redesign Matryoshka Representation Learning within Parametric Spectrum",up:48,href:"https://arxiv.org/abs/2610.26824",abstract:"Matryoshka Representation Learning (MRL) is designed to support flexible representation sizes by jointly optimizing nested prefixes. While effective, this design lacks an explicit constraint to ensure that the leading portion provides a suitable compact encoding. To address this, we propose SpecMRL, which reorganizes the feature space to enable more effective prefix readout. Specifically, we extend MRL with a parameter-derived spectral basis organized with feature importance. SpecMRL otherwise follows standard MRL, with prefix readout performed in the learned spectral space. Experiments on MTE",pdfUrl:"https://arxiv.org/pdf/2610.26824",primaryCategory:"cs.CL",published:"2026-10-19T00:00:00Z"},{id:"2610.24087",title:"OR-License: Evaluating LLM Agents as Real-World Operations Research Practitioners",up:33,href:"https://arxiv.org/abs/2610.24087",abstract:"Can large language model (LLM) agents deliver expert-level operations research (OR) solutions directly from original client materials, without prior expert reformulation? Existing OR benchmarks typically begin with self-contained descriptions or predefined optimization tasks, underrepresenting the translation of original business materials into professionally validated solutions. We introduce OR-License, an end-to-end benchmark of 31 instances across 10 industrial scenarios from paid OR engagements totaling USD 3.68 million. It preserves original requirements, input data, deliverable formats, ",pdfUrl:"https://arxiv.org/pdf/2610.24087",primaryCategory:"cs.CL",published:"2026-10-16T00:00:00Z"},{id:"2610.24960",title:"CoworkEnv: Synthesizing Training Environments for Long-Horizon Cowork Agents",up:30,href:"https://arxiv.org/abs/2610.24960",abstract:"AI coworkers must coordinate tools, communicate across turns, and act on changing workspace state while respecting workflow constraints. Constructing training experience for these capabilities requires coherent requests, service records, tool interfaces, and grading checks. We present CoworkEnv, a capability-guided framework for synthesizing executable training environments for AI coworkers. Workflow requirements guide task construction, and programmatic validation with feedback repair checks generated specifications and grading behavior. Teacher executions yield curated demonstrations for sup",pdfUrl:"https://arxiv.org/pdf/2610.24960",primaryCategory:"cs.AI",published:"2026-10-18T00:00:00Z"},{id:"2610.26216",title:"RoAR-VAE: Improving Latent Diffusability through Robust Prediction",up:23,href:"https://arxiv.org/abs/2610.26216",abstract:"An effective visual tokenizer must preserve image fidelity while producing latents that downstream diffusion models can learn efficiently. Prior work improves latent diffusability through semantic alignment or joint tokenizer--diffusion training. Revisiting REPA-E, a representative approach, we find that removing its diffusion objective and dedicated generative blocks while retaining semantic prediction from corrupted latents yields comparable downstream generation performance under a matched setting. This observation motivates a general principle of robust prediction: generation-relevant info",pdfUrl:"https://arxiv.org/pdf/2610.26216",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.26844",title:"AnyGoal: On World Model Generalization Beyond Expert Rollouts",up:23,href:"https://arxiv.org/abs/2610.26844",abstract:"The goal of a world model is to capture the dynamics of an environment. This has the great appeal that it allows agents to plan and simulate a course of actions with the help of a world model. For these uses to be reliable, however, the learned dynamics must behave well beyond the specific state-action combinations observed in expert rollouts. Despite this, the relationship between data coverage, dynamics generalization, and downstream planning performance remains underexplored. We study this relationship through the lens of compositional generalization: can a world model recombine familiar st",pdfUrl:"https://arxiv.org/pdf/2610.26844",primaryCategory:"cs.AI",published:"2026-10-19T00:00:00Z"},{id:"2610.26663",title:"RoboValue: A Fine-Grained Sim-and-Real Benchmark for Unified Evaluation of Robotic Value Models",up:21,href:"https://arxiv.org/abs/2610.26663",abstract:"Robotic value models assess task execution from visual observations and instructions, providing feedback for policy learning and execution monitoring. However, existing evaluations cover only selected aspects of execution understanding, leaving the reliability of value feedback insufficiently tested. We introduce RoboValue, a fine-grained sim-and-real benchmark for unified evaluation of robotic value models. Its framework evaluates four complementary capability dimensions through shared interfaces: task-state understanding, temporal progress monitoring, failure and recovery reasoning, and valu",pdfUrl:"https://arxiv.org/pdf/2610.26663",primaryCategory:"cs.RO",published:"2026-10-19T00:00:00Z"},{id:"2610.26853",title:"InfiniDream: Open-Ended Photorealistic 3D Worlds Through Procedural Generation",up:20,href:"https://arxiv.org/abs/2610.26853",abstract:"Procedural generation plays a key role in synthetic data creation and game development, offering greater controllability, editability, and diversity than static mesh representations. However, VLM-based code generation often produces relatively simple 3D assets, while sophisticated photorealistic procedural systems require extensive manual development. Existing VLM-guided procedural methods remain largely constrained by predefined factories and APIs, limiting their ability to create novel asset types. We introduce InfiniDream, a VLM-driven framework for open-ended procedural 3D world generation",pdfUrl:"https://arxiv.org/pdf/2610.26853",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.06830",title:"MemPilot: Orchestrating On-Demand Multimodal Memory Curation for LLM Agents",up:19,href:"https://arxiv.org/abs/2610.06830",abstract:"Memory has become integral to the LLM agent ecosystem, supporting information retention and reuse across interactions. However, most existing agent memory systems construct memory in a query-agnostic manner, which can incur unnecessary preprocessing cost and discard details that later prove essential. Recent studies have begun shifting memory processing toward runtime adaptation, but typically specialize in particular operations or fixed processing schemes, leaving flexible control over performance, cost, and latency largely underexplored. To address this challenge, we present \\textbf{MemPilot",pdfUrl:"https://arxiv.org/pdf/2610.06830",primaryCategory:"cs.CL",doi:"https://doi.org/10.52202/085713-0593",year:2025,openalexId:"https://openalex.org/W4407759090",published:"2026-10-05T00:00:00Z"},{id:"2610.26834",title:"Kronecker Delta Rule for Long Context Linear Attention",up:18,href:"https://arxiv.org/abs/2610.26834",abstract:"We propose KronLSTM, a linear attention architecture based on the Kronecker Delta Rule, a novel update rule for associative matrix memories. KronLSTM extends the xLSTM family with a memory-revision mechanism that corrects targeted associations while modifying the memory only along a single direction in matrix space. This minimally invasive memory revision reduces interference with previously stored information compared with delta-rule updates, making it particularly well suited for long-context language modeling. The resulting memory dynamics can be mathematically described as a Markov chain t",pdfUrl:"https://arxiv.org/pdf/2610.26834",primaryCategory:"cs.LG",published:"2026-10-19T00:00:00Z"},{id:"2610.26851",title:"Manga2Animate: An Agentic Framework for Faithful Manga Animation with Script and Storyboard Planning",up:17,href:"https://arxiv.org/abs/2610.26851",abstract:"Adapting existing manga into coherent animation that stays faithful to the source is a valuable yet challenging task. Existing methods either access the manga mainly through text, losing its characters and art style, or feed manga pages directly into video generation models, which misinterpret the manga's structure and produce incorrect storylines. In this paper, we propose Manga2Animate, a multi-agent framework that grounds every stage of generation in the source manga. We decompose the task into two intermediate representations, an animation script and a visual storyboard. Each representatio",pdfUrl:"https://arxiv.org/pdf/2610.26851",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.26848",title:"Where is Physical RSI capability from? An Observational Scaling Law of LLM-as-policy",up:16,href:"https://arxiv.org/abs/2610.26848",abstract:"In this paper, we systematically investigate the mechanisms, scaling behavior, and generalization of physical Recursive self-improvement. We introduce PhysRSI-eval to quantify physical RSI through a five-axis metric: First-Attempt Performance, Efficiency, Success, Budget and Improvement from failure. Different VLMs are evaluated on 18 manipulation tasks under a fixed interaction budget. The analysis of experimental results motivates the Physical Barrel Hypothesis: different capabilities may constrain different parts of improvement. The five-axis metrics also distinguish systems with close publ",pdfUrl:"https://arxiv.org/pdf/2610.26848",primaryCategory:"cs.RO",published:"2026-10-19T00:00:00Z"},{id:"2609.22332",title:"AffordanceWAM: Affordance-Aware Joint World-Action Modeling for Robot Manipulation",up:14,href:"https://arxiv.org/abs/2609.22332",abstract:"Generalizable robot manipulation requires predicting how a scene will evolve, identifying where interactions are feasible, and determining how to act. Action-labeled robot videos directly supervise control but are costly and limited in diversity, whereas egocentric human videos capture diverse interactions but lack robot actions and differ in embodiment and appearance. We introduce AffordanceWAM, an affordance-aware generative World Action Model that represents object-centric spatiotemporal affordance through Scalar Affordance and Affordance Heatmap, within the generated future World. This rep",pdfUrl:"https://arxiv.org/pdf/2609.22332",primaryCategory:"cs.RO",published:"2026-10-18T00:00:00Z"},{id:"2610.25950",title:"AdaExploreBench: Benchmarking LLM Agents for Proactive Exploration and Test-time Adaptation in Evolving Environments",up:13,href:"https://arxiv.org/abs/2610.25950",abstract:"Large Language Model (LLM) agents are increasingly deployed in unfamiliar and evolving environments, requiring them to proactively explore, understand, and adapt to environmental dynamics. However, existing benchmarks rarely test whether agents can proactively discover how an environment works and adapt as it evolves. To address this gap, we introduce AdaExploreBench, a benchmark for proactive exploration and test-time adaptation in evolving environments. By instantiating environmental dynamics as hidden rules, AdaExploreBench requires agents to actively acquire evidence and infer the rules. U",pdfUrl:"https://arxiv.org/pdf/2610.25950",primaryCategory:"cs.CL",crossrefDoi:"https://doi.org/10.1145/3711896.3736570",year:2025,openalexId:"https://openalex.org/W4412877164",published:"2026-10-19T00:00:00Z",crossrefIssued:"2025-08-03"},{id:"2610.26770",title:"HarnessPro: Recursive Harness Self-Improvement with Pareto Optimization for Performance-Cost Trade-offs",up:13,href:"https://arxiv.org/abs/2610.26770",abstract:"Harness development plays a crucial role in building capable AI agents. Recent approaches improve harnesses through recursive self-improvement (RSI), but their performance gains often come with higher execution costs. We introduce HarnessPro, a label-free method for evolving harnesses to improve task performance while reducing execution cost. In this setting, candidate harnesses are evaluated using LLM-generated tests without access to ground-truth solutions or official tests. Specialized agents diagnose execution trajectories, plan updates with different performance-cost priorities, and imple",pdfUrl:"https://arxiv.org/pdf/2610.26770",primaryCategory:"cs.LG",published:"2026-10-19T00:00:00Z"},{id:"2610.17724",title:"Evidence-First Agentic Verification",up:12,href:"https://arxiv.org/abs/2610.17724",abstract:"Long-horizon, semi-verifiable agentic tasks often rely on rubric-based evaluation, but the evidence needed to assess these tasks can be spread across the environment state and the execution trace. A judge may overlook this evidence or accept unsupported claims, including an agent's own reports of success. When rubric verdicts serve as reinforcement-learning rewards, such errors can reinforce undesirable behavior. We introduce Sauron, an evidence-first agentic verifier that investigates both state and trace and relies on a claim only after independently validating it against its source. Bounded",pdfUrl:"https://arxiv.org/pdf/2610.17724",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.25090",title:"Think Visually Across Space and Time: Grounded Reasoning for Video Segmentation",up:12,href:"https://arxiv.org/abs/2610.25090",abstract:"Video Reasoning Segmentation (VRS) requires a model to identify an implicitly described target and predict its pixel-level mask trajectory, while resolving the spatial relations and temporal events that determine the answer. Text-only Chain-of-Thought (CoT) can explain a target choice without making the underlying visual references explicit, leaving a \\emph{video reference gap} between linguistic inference and the evidence distributed across frames. We introduce \\textbf{Temporal Chain of Video Primitives (TCoVP)}, a spatiotemporally grounded form of Video CoT that organizes query-relevant obse",pdfUrl:"https://arxiv.org/pdf/2610.25090",primaryCategory:"cs.CV",published:"2026-10-18T00:00:00Z"},{id:"2610.26081",title:"DeOverlay: A Benchmark and Source-Anchored Flow for Video Overlay Removal",up:12,href:"https://arxiv.org/abs/2610.26081",abstract:"Video overlay removal aims to recover scenes obscured by subtitles, titles, and logos while preserving surrounding content. Existing methods use temporal propagation or source-conditioned generation, but can leave residual overlays and distort scene structure when useful source information is obscured. We propose DeOverlay, a source-anchored flow model that reconstructs the clean video from the source latent with fixed source guidance. Specifically, we train a shared velocity network along paired source-to-clean paths using region-weighted flow matching, enabling successive cor- rections from ",pdfUrl:"https://arxiv.org/pdf/2610.26081",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"W4393160747",title:"ExpeL: LLM Agents Are Experiential Learners",up:0,href:"https://doi.org/10.1609/aaai.v38i17.29936",doi:"https://doi.org/10.1609/aaai.v38i17.29936",year:2024,openalexId:"https://openalex.org/W4393160747"},{id:"W4391620956",title:"Understanding the planning of LLM agents: A survey",up:0,href:"https://doi.org/10.48550/arxiv.2402.02716",doi:"https://doi.org/10.48550/arxiv.2402.02716",year:2024,openalexId:"https://openalex.org/W4391620956"},{id:"W7167900302",title:"LLM Agents Factory: Retrieval of Domain-Specific LLM Agents",up:0,href:"https://doi.org/10.1145/3805712.3808515",doi:"https://doi.org/10.1145/3805712.3808515",year:2026,openalexId:"https://openalex.org/W7167900302"}]}}]);